-- =====================================================
-- 037_financial_reports.sql
-- Pre-Computed Financial Reports
-- =====================================================
--
-- PURPOSE:
-- Store aggregated financial data for fast dashboard queries.
-- Generated by Go worker/cron jobs from raw data tables.
--
-- WHY PRE-COMPUTE?
-- - Complex aggregations are slow on large datasets
-- - Dashboards need instant response times
-- - Historical data doesn't change (can cache)
--
-- GENERATION:
-- - Go worker runs daily (or on-demand)
-- - Queries raw tables, computes aggregates
-- - Inserts/updates report rows
-- =====================================================

-- =====================================================
-- ENUMS
-- =====================================================

CREATE TYPE report_period_enum AS ENUM (
    'daily',
    'weekly',
    'monthly',
    'quarterly',
    'yearly'
);

CREATE TYPE report_status_enum AS ENUM (
    'pending',      -- Scheduled but not generated
    'generating',   -- Currently being generated
    'completed',    -- Successfully generated
    'failed'        -- Generation failed
);

-- =====================================================
-- FINANCIAL REPORTS (Summary)
-- =====================================================
-- One row per period (day/week/month/etc.)

CREATE TABLE financial_reports (
    id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),

    -- -------------------------------------------------
    -- PERIOD
    -- -------------------------------------------------
    report_period report_period_enum NOT NULL,
    period_start DATE NOT NULL,
    period_end DATE NOT NULL,

    -- -------------------------------------------------
    -- STATUS
    -- -------------------------------------------------
    status report_status_enum NOT NULL DEFAULT 'pending',
    generated_at TIMESTAMP,
    generation_duration_ms INTEGER,

    -- -------------------------------------------------
    -- SHIPMENT METRICS
    -- -------------------------------------------------
    total_shipments INTEGER NOT NULL DEFAULT 0,
    total_packages INTEGER NOT NULL DEFAULT 0,
    
    shipments_by_carrier JSONB,
    -- { "fedex": 100, "ups": 50, "purolator": 30 }
    
    shipments_by_service JSONB,
    -- { "ground": 80, "express": 60, "priority": 40 }

    -- -------------------------------------------------
    -- REVENUE (What customers paid us)
    -- -------------------------------------------------
    gross_revenue NUMERIC(14,2) NOT NULL DEFAULT 0,
    discounts_amount NUMERIC(14,2) NOT NULL DEFAULT 0,
    net_revenue NUMERIC(14,2) NOT NULL DEFAULT 0,
    
    taxes_collected NUMERIC(14,2) NOT NULL DEFAULT 0,
    -- HST/GST/PST collected from customers

    revenue_by_carrier JSONB,
    -- { "fedex": 5000, "ups": 2500, ... }

    -- -------------------------------------------------
    -- COSTS (What we paid carriers)
    -- -------------------------------------------------
    carrier_costs NUMERIC(14,2) NOT NULL DEFAULT 0,
    carrier_taxes NUMERIC(14,2) NOT NULL DEFAULT 0,
    
    costs_by_carrier JSONB,
    -- { "fedex": 2500, "ups": 1250, ... }

    -- -------------------------------------------------
    -- GROSS PROFIT
    -- -------------------------------------------------
    gross_profit NUMERIC(14,2) NOT NULL DEFAULT 0,
    gross_margin_percent NUMERIC(5,2),
    
    profit_by_carrier JSONB,
    -- { "fedex": 2500, "ups": 1250, ... }

    -- -------------------------------------------------
    -- COMMISSIONS (What we owe)
    -- -------------------------------------------------
    referral_commissions NUMERIC(14,2) NOT NULL DEFAULT 0,
    affiliate_commissions NUMERIC(14,2) NOT NULL DEFAULT 0,
    sales_commissions NUMERIC(14,2) NOT NULL DEFAULT 0,
    total_commissions NUMERIC(14,2) NOT NULL DEFAULT 0,

    commissions_paid NUMERIC(14,2) NOT NULL DEFAULT 0,
    commissions_pending NUMERIC(14,2) NOT NULL DEFAULT 0,

    -- -------------------------------------------------
    -- NET PROFIT
    -- -------------------------------------------------
    net_profit NUMERIC(14,2) NOT NULL DEFAULT 0,
    net_margin_percent NUMERIC(5,2),

    -- -------------------------------------------------
    -- ADJUSTMENTS
    -- -------------------------------------------------
    adjustment_revenue NUMERIC(14,2) NOT NULL DEFAULT 0,
    adjustment_costs NUMERIC(14,2) NOT NULL DEFAULT 0,
    adjustment_count INTEGER NOT NULL DEFAULT 0,

    -- -------------------------------------------------
    -- REFUNDS
    -- -------------------------------------------------
    refunds_issued NUMERIC(14,2) NOT NULL DEFAULT 0,
    refund_count INTEGER NOT NULL DEFAULT 0,

    -- -------------------------------------------------
    -- WALLET METRICS
    -- -------------------------------------------------
    wallet_topups NUMERIC(14,2) NOT NULL DEFAULT 0,
    wallet_topup_count INTEGER NOT NULL DEFAULT 0,
    
    wallet_refunds NUMERIC(14,2) NOT NULL DEFAULT 0,
    wallet_refund_count INTEGER NOT NULL DEFAULT 0,

    stripe_fees NUMERIC(14,2) NOT NULL DEFAULT 0,

    -- -------------------------------------------------
    -- PAYMENT METHOD BREAKDOWN
    -- -------------------------------------------------
    payments_by_wallet NUMERIC(14,2) NOT NULL DEFAULT 0,
    payments_by_stripe NUMERIC(14,2) NOT NULL DEFAULT 0,
    payments_by_carrier_account NUMERIC(14,2) NOT NULL DEFAULT 0,

    -- -------------------------------------------------
    -- ADMIN/INTERNAL SHIPMENTS
    -- -------------------------------------------------
    carrier_billed_shipments INTEGER NOT NULL DEFAULT 0,
    carrier_billed_cost NUMERIC(14,2) NOT NULL DEFAULT 0,
    -- These are costs with no customer revenue

    -- -------------------------------------------------
    -- CURRENCY
    -- -------------------------------------------------
    currency CHAR(3) NOT NULL DEFAULT 'CAD',

    -- -------------------------------------------------
    -- METADATA
    -- -------------------------------------------------
    notes TEXT,
    metadata JSONB,

    created_at TIMESTAMP WITHOUT TIME ZONE DEFAULT NOW(),
    updated_at TIMESTAMP WITHOUT TIME ZONE DEFAULT NOW(),

    -- -------------------------------------------------
    -- CONSTRAINTS
    -- -------------------------------------------------
    CONSTRAINT uq_financial_report_period
        UNIQUE (report_period, period_start),

    CONSTRAINT chk_fr_period_dates
        CHECK (period_start <= period_end),

    CONSTRAINT chk_fr_net_revenue
        CHECK (ABS(net_revenue - (gross_revenue - discounts_amount)) < 0.01),

    CONSTRAINT chk_fr_gross_profit
        CHECK (ABS(gross_profit - (net_revenue - carrier_costs)) < 1.00),
        -- Allow small rounding differences

    CONSTRAINT chk_fr_net_profit
        CHECK (ABS(net_profit - (gross_profit - total_commissions)) < 1.00)
);

-- =====================================================
-- FINANCIAL REPORT BY ORGANIZATION
-- =====================================================
-- Per-organization breakdown for the same periods

CREATE TABLE financial_reports_by_org (
    id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),

    -- -------------------------------------------------
    -- LINKAGE
    -- -------------------------------------------------
    financial_report_id UUID NOT NULL
        REFERENCES financial_reports(id)
        ON DELETE CASCADE,

    organization_id UUID NOT NULL
        REFERENCES organizations(id)
        ON DELETE CASCADE,

    -- -------------------------------------------------
    -- PERIOD (Denormalized for easier queries)
    -- -------------------------------------------------
    report_period report_period_enum NOT NULL,
    period_start DATE NOT NULL,

    -- -------------------------------------------------
    -- METRICS
    -- -------------------------------------------------
    total_shipments INTEGER NOT NULL DEFAULT 0,
    total_packages INTEGER NOT NULL DEFAULT 0,

    gross_revenue NUMERIC(14,2) NOT NULL DEFAULT 0,
    discounts_amount NUMERIC(14,2) NOT NULL DEFAULT 0,
    net_revenue NUMERIC(14,2) NOT NULL DEFAULT 0,

    carrier_costs NUMERIC(14,2) NOT NULL DEFAULT 0,
    gross_profit NUMERIC(14,2) NOT NULL DEFAULT 0,
    gross_margin_percent NUMERIC(5,2),

    total_commissions NUMERIC(14,2) NOT NULL DEFAULT 0,
    net_profit NUMERIC(14,2) NOT NULL DEFAULT 0,

    -- -------------------------------------------------
    -- CARRIER BREAKDOWN
    -- -------------------------------------------------
    revenue_by_carrier JSONB,
    shipments_by_carrier JSONB,

    -- -------------------------------------------------
    -- TIMESTAMPS
    -- -------------------------------------------------
    created_at TIMESTAMP WITHOUT TIME ZONE DEFAULT NOW(),

    -- -------------------------------------------------
    -- CONSTRAINTS
    -- -------------------------------------------------
    CONSTRAINT uq_fr_org_period
        UNIQUE (organization_id, report_period, period_start)
);

-- =====================================================
-- FINANCIAL REPORT BY CARRIER
-- =====================================================
-- Per-carrier breakdown

CREATE TABLE financial_reports_by_carrier (
    id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),

    financial_report_id UUID NOT NULL
        REFERENCES financial_reports(id)
        ON DELETE CASCADE,

    carrier_id UUID NOT NULL
        REFERENCES carriers(id)
        ON DELETE CASCADE,

    report_period report_period_enum NOT NULL,
    period_start DATE NOT NULL,

    -- -------------------------------------------------
    -- METRICS
    -- -------------------------------------------------
    total_shipments INTEGER NOT NULL DEFAULT 0,
    total_packages INTEGER NOT NULL DEFAULT 0,

    gross_revenue NUMERIC(14,2) NOT NULL DEFAULT 0,
    carrier_costs NUMERIC(14,2) NOT NULL DEFAULT 0,
    gross_profit NUMERIC(14,2) NOT NULL DEFAULT 0,
    gross_margin_percent NUMERIC(5,2),

    -- Service level breakdown
    shipments_by_service JSONB,
    revenue_by_service JSONB,

    created_at TIMESTAMP WITHOUT TIME ZONE DEFAULT NOW(),

    CONSTRAINT uq_fr_carrier_period
        UNIQUE (carrier_id, report_period, period_start)
);

-- =====================================================
-- INDEXES
-- =====================================================

-- Financial Reports
CREATE INDEX idx_fr_period ON financial_reports(report_period);
CREATE INDEX idx_fr_period_start ON financial_reports(period_start);
CREATE INDEX idx_fr_status ON financial_reports(status);
CREATE INDEX idx_fr_period_range ON financial_reports(report_period, period_start, period_end);

-- By Organization
CREATE INDEX idx_fr_org_org ON financial_reports_by_org(organization_id);
CREATE INDEX idx_fr_org_report ON financial_reports_by_org(financial_report_id);
CREATE INDEX idx_fr_org_period ON financial_reports_by_org(period_start);

-- By Carrier
CREATE INDEX idx_fr_carrier_carrier ON financial_reports_by_carrier(carrier_id);
CREATE INDEX idx_fr_carrier_report ON financial_reports_by_carrier(financial_report_id);
CREATE INDEX idx_fr_carrier_period ON financial_reports_by_carrier(period_start);

-- =====================================================
-- HELPER VIEW: Latest Reports
-- =====================================================

CREATE OR REPLACE VIEW v_latest_financial_reports AS
SELECT 
    fr.*,
    
    -- Previous period comparison
    LAG(fr.net_revenue) OVER (
        PARTITION BY fr.report_period 
        ORDER BY fr.period_start
    ) AS prev_period_revenue,
    
    LAG(fr.net_profit) OVER (
        PARTITION BY fr.report_period 
        ORDER BY fr.period_start
    ) AS prev_period_profit

FROM financial_reports fr
WHERE fr.status = 'completed'
ORDER BY fr.period_start DESC;

